/**
 * Parity with the upstream Python colour-management implementation.
 *
 * `tests/fixtures/match/colour-management-cases.json` is generated by running
 * the MIT-licensed `reference-match` `lutcore.colour_management` module (and
 * `fit_dwg_residual_lut`) on a deterministic input set; regeneration steps live
 * in `tests/fixtures/match/README.md`. This test is the guard that keeps the
 * TypeScript port honest: these transforms decide what a DWG or S-Log3 cube
 * *means* inside Resolve, so "close enough" is not a category here.
 */
import { readFileSync } from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";
import {
  dwgIntermediateToRec709Gamma24,
  precompensateDwgForResolveRec709,
  rec709Gamma24ToDwgIntermediate,
  resolveDwgToRec709Gamma24,
  slog3ToRec709Gamma24,
} from "../../../../src/shared/match/colour-management";
import { fitDwgResidualLut } from "../../../../src/shared/match/global-match";

interface Fixture {
  samples: [number, number, number][];
  dwg_to_display: [number, number, number][];
  display_to_dwg: [number, number, number][];
  resolve_dwg_output: [number, number, number][];
  precompensate_dwg: [number, number, number][];
  slog3_cine_full: [number, number, number][];
  slog3_cine_video: [number, number, number][];
  slog3_full_gamut: [number, number, number][];
  dwg_fit: {
    source: [number, number, number][];
    reference: [number, number, number][];
    residual: number[][];
    dimension: number;
  };
}

const fixture = JSON.parse(
  readFileSync(
    path.join(process.cwd(), "tests/fixtures/match/colour-management-cases.json"),
    "utf8",
  ),
) as Fixture;

function packed(values: [number, number, number][]): Float32Array {
  const result = new Float32Array(values.length * 3);
  values.forEach((value, index) => {
    result[index * 3] = value[0];
    result[index * 3 + 1] = value[1];
    result[index * 3 + 2] = value[2];
  });
  return result;
}

function expectClose(
  actual: readonly number[],
  expected: readonly number[],
  label: string,
  tolerance = 1e-5,
): void {
  expect(actual.length).toBe(expected.length);
  let worst = 0;
  let worstIndex = -1;
  for (let index = 0; index < expected.length; index += 1) {
    const delta = Math.abs(actual[index] - expected[index]);
    if (delta > worst) {
      worst = delta;
      worstIndex = index;
    }
  }
  expect(
    worst,
    `${label} 最大偏差 ${worst}（第 ${worstIndex} 个值，输入 ${JSON.stringify(
      fixture.samples[Math.floor(worstIndex / 3)],
    )}）`,
  ).toBeLessThanOrEqual(tolerance);
}

describe("colour management parity with the upstream implementation", () => {
  it("DWG/DI → Rec.709 Gamma 2.4 与上游逐点一致", () => {
    const actual = fixture.samples.flatMap(([red, green, blue]) =>
      dwgIntermediateToRec709Gamma24(red, green, blue),
    );
    expectClose(actual, fixture.dwg_to_display.flat(), "dwg_to_display");
  });

  it("Rec.709 Gamma 2.4 → DWG/DI 与上游逐点一致", () => {
    const actual = fixture.samples.flatMap(([red, green, blue]) =>
      rec709Gamma24ToDwgIntermediate(Math.min(1, red), Math.min(1, green), Math.min(1, blue)),
    );
    expectClose(actual, fixture.display_to_dwg.flat(), "display_to_dwg");
  });

  it("Resolve 709 输出响应模型与上游逐点一致", () => {
    const actual = fixture.samples.flatMap(([red, green, blue]) =>
      resolveDwgToRec709Gamma24(red, green, blue),
    );
    expectClose(actual, fixture.resolve_dwg_output.flat(), "resolve_dwg_output");
  });

  it("DWG 输出预补偿与上游逐点一致", () => {
    // 只比较真实可出现的 DWG/DI 码值（0..1）。超过 1 的码值在双向矩阵
    // 往返中会出现灾难性抵消：上游是 float32、这里是 float64，两边都只是
    // 在放大浮点噪声，拿它做“一致性”没有意义。
    const plausible = fixture.samples
      .map((sample, index) => ({ sample, index }))
      .filter(({ sample }) => sample.every((value) => value >= 0 && value <= 1));
    const actual = plausible.flatMap(({ sample }) =>
      precompensateDwgForResolveRec709(sample[0], sample[1], sample[2]),
    );
    const expected = plausible.flatMap(({ index }) => fixture.precompensate_dwg[index]);
    // 容差 5e-4：DI 的 log 编码在近黑区把 float32 与 float64 的差异
    // 放大到半个 12-bit 步长量级；上游跑的是 float32 torch。
    expectClose(actual, expected, "precompensate_dwg", 5e-4);
  });

  it("S-Log3 三种组合的还原与上游逐点一致", () => {
    const cases = [
      { key: "slog3_cine_full", gamut: "sgamut3-cine", inputRange: "full" },
      { key: "slog3_cine_video", gamut: "sgamut3-cine", inputRange: "video" },
      { key: "slog3_full_gamut", gamut: "sgamut3", inputRange: "full" },
    ] as const;
    for (const testCase of cases) {
      const actual = fixture.samples.flatMap(([red, green, blue]) =>
        slog3ToRec709Gamma24(red, green, blue, {
          gamut: testCase.gamut,
          inputRange: testCase.inputRange,
        }),
      );
      expectClose(actual, fixture[testCase.key].flat(), testCase.key, 5e-5);
    }
  });

  it("DWG 直拟与上游残差体一致", () => {
    const dimension = fixture.dwg_fit.dimension;
    const lut = fitDwgResidualLut(
      packed(fixture.dwg_fit.source),
      packed(fixture.dwg_fit.reference),
      dimension,
    );
    // 上游残差体是 [channel][blue][green][red]，本仓库存的是交错的
    // [blue][green][red][channel]；这里显式重排，不靠“看起来差不多”。
    const plane = dimension * dimension;
    const expected = new Array<number>(lut.data.length).fill(0);
    for (let blue = 0; blue < dimension; blue += 1) {
      for (let green = 0; green < dimension; green += 1) {
        for (let red = 0; red < dimension; red += 1) {
          const source = (blue * dimension + green) * dimension + red;
          const target = (blue * plane + green * dimension + red) * 3;
          for (let channel = 0; channel < 3; channel += 1) {
            expected[target + channel] = fixture.dwg_fit.residual[channel][source];
          }
        }
      }
    }
    expectClose(Array.from(lut.data), expected, "dwg_fit", 2e-4);
  });
});
